// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Typed errors, plain messages, exit codes 0-4
// Flo: error value > exit code (0 ok, 1 fail, 2 usage, 3 page changed, 4 blocked) > message (what, why, fix)
// I/O: error (caller) > exit code, Mesg of 3 short lines
// ===================================================================
const std = @import("std");
const CF = .{ .okay = 0, .fail = 1, .usag = 2, .drif = 3, .bloc = 4 };
pub const Erro = error{ BadUsage, BadConfig, Drift, Halted, CapHit, QuietHour, NeedApprove, NeedLogin, Paused, NoBrowser, BrowFail, Timeout, Closed, TooBig, BadFrame, BadHandshake, CdpError, EvalFail, NoElement, NoJob, Dupe, NavFail, SqliOpen, SqliExec, SqliPrep, SqliBind, SqliStep, NoConsent, Locked, Unsafe, WaitTimeout, BadFlow, NoSecret, Fail };
pub const Mesg = struct { what: []const u8, whyz: []const u8, fixz: []const u8 };
pub fn exitCode(erro: anyerror) u8 { return switch (erro) { error.BadUsage, error.NoJob, error.BadConfig, error.BadFlow, error.NoSecret => CF.usag, error.Drift, error.NoElement => CF.drif, error.Halted, error.CapHit, error.QuietHour, error.NeedApprove, error.NeedLogin, error.Paused, error.NoConsent, error.Locked, error.Unsafe, error.WaitTimeout => CF.bloc, else => CF.fail }; }
pub fn mesg(erro: anyerror) Mesg { return mesgLang(erro, "en"); }
pub fn mesgLang(erro: anyerror, lang: []const u8) Mesg { _ = lang; return switch (erro) { error.BadUsage => .{ .what = "bad usage", .whyz = "unknown command or flag", .fixz = "run: zr-zrow-webs help" }, error.NoJob => .{ .what = "unknown job", .whyz = "no such job name", .fixz = "run: zr-zrow-webs jobs" }, error.BadConfig => .{ .what = "bad config", .whyz = "aa-conf-main.json has a bad value", .fixz = "fix the key or remove the file for defaults" }, error.BadFlow => .{ .what = "bad routine", .whyz = "no routine with that name, or it has no jobs", .fixz = "check flow_list in aa-conf-main.json" }, error.NoSecret => .{ .what = "no login on file", .whyz = "the secret file with username and password is missing", .fixz = "run: zr-zrow-webs secret (2 lines on stdin: email, password)" }, error.Drift => .{ .what = "page changed", .whyz = "the page does not look as expected", .fixz = "run: zr-zrow-webs doctor, then fix the labels" }, error.Halted => .{ .what = "stopped by ZenRows", .whyz = "captcha, 2FA, email code or a block page was seen", .fixz = "finish it in the browser window, then run again" }, error.Unsafe => .{ .what = "stopped for safety", .whyz = "ZenRows limited, banned or rate-limited the account", .fixz = "wait 24 hours, then run again at a slower pace" }, error.CapHit => .{ .what = "daily limit reached", .whyz = "this kind of action hit its cap", .fixz = "wait, or raise the capz_* key in aa-conf-main.json" }, error.QuietHour => .{ .what = "quiet hours", .whyz = "no activity during quiet hours", .fixz = "run later, or change quie_hour_rang" }, error.NeedApprove => .{ .what = "needs your approval", .whyz = "risky action (payment, cancel, delete, key revoke)", .fixz = "run: zr-zrow-webs plan, then zr-zrow-webs approve all (or re-run with --live --force)" }, error.NeedLogin => .{ .what = "not logged in", .whyz = "ZenRows shows a login page", .fixz = "run: zr-zrow-webs login, then log in by hand in the window" }, error.NoConsent => .{ .what = "no consent on file", .whyz = "live runs need your OK about the ZenRows terms risk", .fixz = "run: zr-zrow-webs setup" }, error.Locked => .{ .what = "already running", .whyz = "another zr-zrow-webs run uses this profile", .fixz = "wait for it to finish" }, error.WaitTimeout => .{ .what = "waited too long", .whyz = "the step that needs you was not finished in time", .fixz = "finish it in the browser, then run again" }, error.Paused => .{ .what = "paused", .whyz = "pause flag is set", .fixz = "run: zr-zrow-webs resume" }, error.NoBrowser => .{ .what = "no browser", .whyz = "Chrome or Edge not found", .fixz = "install Chrome, or set brow_exec_path" }, error.BrowFail => .{ .what = "browser failed", .whyz = "the browser did not start or closed", .fixz = "close other windows using the zr profile, retry" }, error.Timeout => .{ .what = "timeout", .whyz = "no answer in time", .fixz = "retry; raise brow_time_seco if it repeats" }, error.NoElement => .{ .what = "button or box not found", .whyz = "label not on the page", .fixz = "run: zr-zrow-webs doctor, then fix labl_over" }, error.Dupe => .{ .what = "already done", .whyz = "same action was done before", .fixz = "nothing to do, or run: zr-zrow-webs unlock <key>" }, else => .{ .what = "failed", .whyz = @errorName(erro), .fixz = "re-run with --json and check status" } }; }
